#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int n_input, total_count, answer_value;
vector<int> buckets[15];
long long prefix_sum[15];

void generate_combinations(int depth, int number);
void process_number(int x);

int main() {
    cin >> n_input;
    generate_combinations(0, 0);
    for (int i = 0; i <= 7; ++i) {
        sort(buckets[i].begin(), buckets[i].end());
    }
    total_count = 0;
    for (int i = 1; i <= 9; ++i) {
        process_number(i);
    }
    cout << answer_value << "\n";
    return 0;
}

void generate_combinations(int depth, int num) {
    if (depth == 7) return;
    total_count++;
    int val = ((total_count - num) % 998244353 + 998244353) % 998244353;
    buckets[depth].push_back(val);
    prefix_sum[depth] = (prefix_sum[depth] + val) % 1000000007;
    for (int digit = 0; digit <= 9; ++digit) {
        generate_combinations(depth + 1, num * 10 + digit);
    }
}

void process_number(int x) {
    if (x > n_input) return;
    if (x * 1000000 + 999999 <= n_input && x * 10000000 > n_input) {
        int current_total = total_count;
        for (int i = 0, factor = 1; i <= 6; ++i, factor *= 10) {
            int size = buckets[i].size();
            int diff = ((current_total - x * factor) % 998244353 + 998244353) % 998244353;
            int pos = (int)(lower_bound(buckets[i].begin(), buckets[i].end(), 1000000000 - diff) - buckets[i].begin());
            answer_value = (answer_value + diff * size + prefix_sum[i]) % 1000000007;
            answer_value = (answer_value - 998244353 * (size - pos) % 1000000007 + 1000000007) % 1000000007;
            current_total += size;
        }
        return;
    }
    total_count++;
    answer_value = (answer_value + ((total_count - x) % 998244353 + 998244353) % 998244353) % 1000000007;
    for (int digit = 0; digit <= 9; ++digit) {
        process_number(x * 10 + digit);
    }
}
